/**
 * Strict parser for telemetry received using the single-device flespi ACL.
 * Only data-bearing Shelly frames are accepted. A partial NotifyStatus does
 * not imply an ON or OFF transition if it omits `output`.
 *
 * The receipt timestamp is generated by the backend. Untrusted device `ts`
 * values must not override it. This is NOT RPC execution confirmation.
 */
export interface FlespiShellyTelemetry {
  connectivityStatus: 'ONLINE';
  isOn?: boolean;
  currentPowerW?: number | null;
  energyTotalKwh?: number | null;
  voltageV?: number | null;
  currentA?: number | null;
  frequencyHz?: number | null;
  temperatureC?: number | null;
  readAt: string;
}

type ShellyFrameKind = 'shelly-switch' | 'shelly-events';
const INVALID = Symbol('invalid-telemetry');
type NumericField = number | null | undefined | typeof INVALID;

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Null means unavailable, not zero. Negative power/energy is not valid here. */
function measurement(value: unknown, nonnegative: boolean): NumericField {
  if (value === undefined || value === null) return value;
  if (typeof value !== 'number' || !Number.isFinite(value) ||
      (nonnegative && value < 0)) return INVALID;
  return value;
}

export function parseFlespiShellyTelemetry(
  kind: ShellyFrameKind,
  payload: Record<string, unknown>,
  switchId: number,
  receivedAt: Date = new Date(),
): FlespiShellyTelemetry | null {
  let data = payload;
  if (kind === 'shelly-events') {
    if (payload.method !== 'NotifyStatus' &&
        payload.method !== 'NotifyFullStatus') return null;
    if (!record(payload.params)) return null;
    const switchData = payload.params[`switch:${switchId}`];
    if (!record(switchData)) return null;
    data = switchData;
  }

  if (data.output !== undefined && typeof data.output !== 'boolean') {
    return null;
  }
  if (data.aenergy !== undefined && data.aenergy !== null &&
      !record(data.aenergy)) return null;
  if (data.temperature !== undefined && data.temperature !== null &&
      !record(data.temperature)) return null;

  const power = measurement(data.apower, true);
  const voltage = measurement(data.voltage, true);
  const current = measurement(data.current, true);
  const frequency = measurement(data.freq, true);
  const energyWh = record(data.aenergy)
    ? measurement(data.aenergy.total, true) : undefined;
  const temperatureC = record(data.temperature)
    ? measurement(data.temperature.tC, false) : undefined;

  if ([power, voltage, current, frequency, energyWh, temperatureC]
    .some((value) => value === INVALID)) return null;

  const validFields = [data.output, power, voltage, current, frequency,
    energyWh, temperatureC];
  if (!validFields.some((value) => value !== undefined && value !== null)) {
    return null;
  }

  return {
    connectivityStatus: 'ONLINE',
    isOn: data.output as boolean | undefined,
    currentPowerW: power as number | null | undefined,
    voltageV: voltage as number | null | undefined,
    currentA: current as number | null | undefined,
    frequencyHz: frequency as number | null | undefined,
    energyTotalKwh: typeof energyWh === 'number'
      ? energyWh / 1000 : energyWh as null | undefined,
    temperatureC: temperatureC as number | null | undefined,
    readAt: receivedAt.toISOString(),
  };
}
